<template>
  <section class="playlists-page">
    <header class="playlists-hero">
      <div><p class="eyebrow">YOUR CURATION / PLAYLISTS</p><h1>Bộ sưu tập<br /><em>của riêng bạn.</em></h1><p>Biến 188 bài hát thành những không gian nghe nhạc có chủ đích, theo tâm trạng và khoảnh khắc của bạn.</p></div>
      <div class="hero-mark">▤<small>CURATE<br />YOUR<br />MOMENT</small></div>
    </header>

    <div class="playlist-layout">
      <aside class="playlist-sidebar">
        <div class="sidebar-title"><span>PLAYLISTS</span><b>{{ playlists.length }}</b></div>
        <TransitionGroup name="flip-list" tag="div" class="playlist-tabs"><button v-for="playlist in playlists" :key="playlist.id" class="playlist-tab" :class="{ active: selectedId === playlist.id }" type="button" @click="selectedId = playlist.id"><span class="playlist-tab-icon">◒</span><span><strong>{{ playlist.name }}</strong><small>{{ playlist.songIds.length }} bài hát</small></span><i>›</i></button></TransitionGroup>
        <div v-if="!playlists.length" class="playlist-empty">Chưa có playlist.<br />Tạo bộ sưu tập đầu tiên.</div>
        <form class="create-form" @submit.prevent="createNew"><label><span>TẠO PLAYLIST MỚI</span><input v-model.trim="newName" placeholder="Ví dụ: Đêm mưa" maxlength="80" /></label><input v-model.trim="newDescription" class="description-input" placeholder="Mô tả ngắn (không bắt buộc)" maxlength="160" /><button type="submit" :disabled="!newName">+ Tạo playlist</button></form>
      </aside>

      <main v-if="selectedPlaylist" class="playlist-detail">
        <div class="detail-head"><div><p class="eyebrow">LISTENING ROOM / {{ String(selectedPlaylist.songIds.length).padStart(2, '0') }} TRACKS</p><h2>{{ selectedPlaylist.name }}</h2><p>{{ selectedPlaylist.description || 'Một tuyển tập được chọn riêng cho những lần nghe thật trọn vẹn.' }}</p></div><div class="detail-actions"><button class="play-all" type="button" :disabled="!playlistSongs.length" @click="playAll">▶ Phát tất cả</button><button class="icon-action" type="button" title="Xóa playlist" @click="removePlaylist">×</button></div></div>
        <div class="playlist-rule"><span>CURATED {{ formatDate(selectedPlaylist.updatedAt) }}</span><span>{{ playlistSongs.length }} / {{ songs.length }} bài trong thư viện</span></div>

        <div class="add-track"><div><strong>Thêm bài hát vào playlist</strong><small>Chọn từ toàn bộ thư viện LuNu Music</small></div><div class="add-track-controls"><select v-model="songToAdd" aria-label="Chọn bài hát để thêm"><option value="">Chọn một bài hát...</option><option v-for="song in availableSongs" :key="song.id" :value="song.id">{{ song.title }} — {{ song.artist || 'Unknown artist' }}</option></select><button type="button" :disabled="!songToAdd" @click="addSelectedSong">Thêm</button></div></div>

        <TransitionGroup v-if="playlistSongs.length" name="flip-list" tag="div" class="track-list"><article v-for="(song, index) in playlistSongs" :key="song.id" class="track-row"><span class="track-number">{{ String(index + 1).padStart(2, '0') }}</span><button class="track-cover" type="button" @click="emit('play-song', song, playlistSongs)"><img :src="song.cover || fallbackCover" :alt="`Bìa ${song.title}`" loading="lazy" @error="handleImageError" /><span>▶</span></button><button class="track-copy" type="button" @click="emit('play-song', song, playlistSongs)"><strong>{{ song.title }}</strong><small>{{ song.artist || 'Unknown artist' }}</small></button><span class="track-album">{{ song.album || 'SINGLE' }}</span><button class="remove-track" type="button" title="Xóa khỏi playlist" @click="removeSongFromPlaylist(song.id)">×</button></article></TransitionGroup>
        <div v-else class="detail-empty"><span>◌</span><h3>Playlist đang trống</h3><p>Thêm những bài hát đầu tiên để bắt đầu không gian nghe nhạc này.</p></div>
      </main>
      <main v-else class="playlist-detail detail-empty"><span>✦</span><h3>Tạo playlist đầu tiên</h3><p>Một playlist nhỏ có thể thay đổi hoàn toàn cách bạn nghe nhạc.</p></main>
    </div>
  </section>
</template>

<script setup>
import { computed, ref, watch } from 'vue';
import songs from '../data/songs';
import { usePlaylists } from '../composables/usePlaylists';
import { useDialog } from '../composables/useDialog';

const props = defineProps({ songs: { type: Array, default: () => songs } });
const emit = defineEmits(['play-song']);
const fallbackCover = '/images/ChoCiu.jpg';
const handleImageError = (event) => { const image = event.currentTarget; if (!image || image.dataset.fallbackApplied === 'true') return; image.dataset.fallbackApplied = 'true'; image.src = fallbackCover; };
const { playlists, activePlaylistId, selectPlaylist, createPlaylist, deletePlaylist, addSong, removeSong, getSongs } = usePlaylists();
const { confirmDialog } = useDialog();
const selectedId = ref(activePlaylistId.value || playlists.value[0]?.id || null);
const newName = ref('');
const newDescription = ref('');
const songToAdd = ref('');
const selectedPlaylist = computed(() => playlists.value.find((playlist) => String(playlist.id) === String(selectedId.value)) || playlists.value[0] || null);
const playlistSongs = computed(() => getSongs(selectedPlaylist.value, props.songs));
const availableSongs = computed(() => props.songs.filter((song) => !selectedPlaylist.value?.songIds?.some((id) => String(id) === String(song.id))));
const createNew = () => { const playlist = createPlaylist(newName.value, newDescription.value); if (!playlist) return; selectedId.value = playlist.id; selectPlaylist(playlist.id); newName.value = ''; newDescription.value = ''; };
const addSelectedSong = () => { if (!selectedPlaylist.value || !songToAdd.value) return; addSong(selectedPlaylist.value.id, songToAdd.value); songToAdd.value = ''; };
const removeSongFromPlaylist = (songId) => removeSong(selectedPlaylist.value?.id, songId);
const removePlaylist = async () => { if (!selectedPlaylist.value || !await confirmDialog(`Xóa playlist “${selectedPlaylist.value.name}”?`, { title: 'Xóa playlist', confirmLabel: 'Xóa playlist', danger: true })) return; const currentIndex = playlists.value.findIndex((item) => item.id === selectedPlaylist.value.id); deletePlaylist(selectedPlaylist.value.id); selectedId.value = playlists.value[currentIndex]?.id || playlists.value[0]?.id || null; };
const playAll = () => { if (playlistSongs.value[0]) emit('play-song', playlistSongs.value[0], playlistSongs.value); };
const formatDate = (value) => { if (!value) return 'VỪA CẬP NHẬT'; try { return new Date(value).toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' }); } catch { return 'VỪA CẬP NHẬT'; } };
watch(selectedId, (value) => selectPlaylist(value), { immediate: true });
watch(playlists, (value) => { if (!value.some((playlist) => String(playlist.id) === String(selectedId.value))) selectedId.value = value[0]?.id || null; }, { deep: true });
</script>

<style scoped>
.playlists-page { max-width: 1440px; margin: 0 auto; padding-bottom: 60px; }.eyebrow { margin: 0 0 12px; color: var(--gold); font: 9px var(--font-mono); letter-spacing: 2px; }.playlists-hero { display: flex; align-items: center; justify-content: space-between; min-height: 240px; padding: clamp(28px, 5vw, 62px); border: 1px solid rgba(255,255,255,.08); border-radius: 28px; background: radial-gradient(circle at 75% 40%, rgba(245,185,122,.19), transparent 28%), linear-gradient(118deg, rgba(38,42,55,.96), rgba(16,19,27,.82)); overflow: hidden; }.playlists-hero h1 { margin: 0; color: var(--text-main); font: 500 clamp(39px, 5vw, 65px)/.98 var(--font-display); letter-spacing: -2px; }.playlists-hero h1 em { color: var(--gold); font-style: italic; }.playlists-hero p:last-child { max-width: 470px; margin-top: 18px; color: var(--text-sub); font-size: 13px; line-height: 1.65; }.hero-mark { display: flex; align-items: center; gap: 15px; color: var(--gold); font: 800 clamp(65px, 10vw, 130px)/.8 var(--font-display); opacity: .74; transform: rotate(-8deg); }.hero-mark small { color: var(--text-faint); font: 8px/1.5 var(--font-mono); letter-spacing: 1.6px; }.playlist-layout { display: grid; grid-template-columns: 275px minmax(0, 1fr); gap: 22px; margin-top: 24px; }.playlist-sidebar { padding: 17px; border: 1px solid var(--hairline-soft); border-radius: 18px; background: rgba(255,255,255,.025); }.sidebar-title { display: flex; align-items: center; justify-content: space-between; padding: 4px 4px 12px; color: var(--text-faint); font: 9px var(--font-mono); letter-spacing: 1.7px; }.sidebar-title b { color: var(--gold); font-weight: 600; }.playlist-tabs { display: flex; flex-direction: column; gap: 3px; }
.playlist-tab { display: flex; align-items: center; gap: 10px; width: 100%; padding: 10px 8px; border: 1px solid transparent; border-radius: 10px; background: transparent; color: var(--text-main); text-align: left; cursor: pointer; }.playlist-tab:hover, .playlist-tab.active { border-color: var(--hairline-soft); background: rgba(245,185,122,.08); }.playlist-tab-icon { display: grid; place-items: center; width: 29px; height: 29px; border-radius: 9px; background: rgba(245,185,122,.11); color: var(--gold); font-size: 15px; }.playlist-tab span:nth-child(2) { display: flex; flex: 1; flex-direction: column; min-width: 0; }.playlist-tab strong, .playlist-tab small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.playlist-tab strong { font-size: 11px; }.playlist-tab small { margin-top: 4px; color: var(--text-faint); font-size: 9px; }.playlist-tab i { color: var(--text-faint); font-size: 18px; font-style: normal; }.playlist-tab.active i { color: var(--gold); }.playlist-empty { padding: 18px 5px; color: var(--text-faint); font-size: 10px; line-height: 1.6; }.create-form { padding-top: 17px; margin-top: 15px; border-top: 1px solid var(--hairline-soft); }.create-form label { display: block; }.create-form label span { display: block; margin-bottom: 7px; color: var(--text-faint); font: 8px var(--font-mono); letter-spacing: 1.2px; }.create-form input, .add-track select { width: 100%; border: 1px solid var(--hairline-soft); border-radius: 9px; outline: 0; background: rgba(3,5,9,.3); color: var(--text-main); font-size: 10px; }.create-form input { padding: 9px 10px; }.create-form input:focus, .add-track select:focus { border-color: rgba(245,185,122,.55); }.description-input { margin-top: 7px; }.create-form button, .add-track-controls button { margin-top: 8px; border: 1px solid rgba(245,185,122,.35); border-radius: 8px; padding: 8px 10px; background: rgba(245,185,122,.09); color: var(--gold-bright); cursor: pointer; font-size: 10px; }.create-form button:disabled, .add-track-controls button:disabled { opacity: .4; cursor: not-allowed; }.playlist-detail { min-width: 0; padding: clamp(20px, 3vw, 34px); border: 1px solid var(--hairline-soft); border-radius: 21px; background: linear-gradient(145deg, rgba(255,255,255,.035), rgba(255,255,255,.015)); }.detail-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }.detail-head h2 { margin: 6px 0 0; color: var(--text-main); font: 500 clamp(28px, 4vw, 48px) var(--font-display); }.detail-head p:last-child { max-width: 550px; margin-top: 8px; color: var(--text-sub); font-size: 11px; line-height: 1.5; }.detail-actions { display: flex; gap: 8px; }.play-all, .icon-action { border-radius: 10px; cursor: pointer; }.play-all { border: 0; padding: 10px 13px; background: var(--gold); color: #171218; font-size: 10px; font-weight: 800; }.play-all:disabled { opacity: .45; cursor: not-allowed; }.icon-action { width: 35px; border: 1px solid rgba(255,109,125,.2); background: transparent; color: var(--crimson); font-size: 18px; }.playlist-rule { display: flex; justify-content: space-between; gap: 10px; padding: 18px 0 15px; margin-top: 20px; border-top: 1px solid var(--hairline-soft); color: var(--text-faint); font: 8px var(--font-mono); letter-spacing: 1.2px; }.add-track { display: flex; align-items: center; justify-content: space-between; gap: 15px; padding: 13px; margin-bottom: 15px; border: 1px dashed rgba(245,185,122,.22); border-radius: 12px; background: rgba(245,185,122,.035); }.add-track strong, .add-track small { display: block; }.add-track strong { color: var(--text-main); font-size: 11px; }.add-track small { margin-top: 4px; color: var(--text-faint); font-size: 9px; }.add-track-controls { display: flex; align-items: center; gap: 7px; width: min(390px, 48%); }.add-track select { flex: 1; padding: 9px; }.add-track-controls button { margin: 0; flex: none; }.track-list { border-top: 1px solid var(--hairline-soft); }.track-row { display: grid; grid-template-columns: 28px 43px minmax(0, 1fr) 90px 27px; align-items: center; gap: 12px; min-height: 65px; border-bottom: 1px solid var(--hairline-soft); }.track-number { color: var(--text-faint); font: 9px var(--font-mono); }.track-cover { position: relative; width: 43px; height: 43px; padding: 0; overflow: hidden; border: 0; border-radius: 8px; background: transparent; cursor: pointer; }.track-cover img { width: 100%; height: 100%; object-fit: cover; }.track-cover span { position: absolute; inset: 0; display: grid; place-items: center; background: rgba(5,7,12,.56); color: var(--gold); opacity: 0; }.track-cover:hover span { opacity: 1; }.track-copy { min-width: 0; padding: 0; border: 0; background: transparent; color: var(--text-main); text-align: left; cursor: pointer; }.track-copy strong, .track-copy small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.track-copy strong { font-size: 11px; }.track-copy small { margin-top: 4px; color: var(--text-sub); font-size: 9px; }.track-album { overflow: hidden; color: var(--text-faint); text-overflow: ellipsis; white-space: nowrap; font: 8px var(--font-mono); }.remove-track { width: 27px; height: 27px; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--text-faint); cursor: pointer; font-size: 16px; }.remove-track:hover { border-color: rgba(255,109,125,.2); color: var(--crimson); }.detail-empty { display: grid; min-height: 370px; place-items: center; align-content: center; text-align: center; }.detail-empty > span { color: var(--gold); font-size: 28px; }.detail-empty h3 { margin-top: 12px; color: var(--text-main); font: 500 21px var(--font-display); }.detail-empty p { margin-top: 7px; color: var(--text-sub); font-size: 11px; }
@media (max-width: 900px) { .playlist-layout { grid-template-columns: 1fr; }.playlist-sidebar { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 5px; }.sidebar-title, .create-form { grid-column: 1 / -1; }.create-form { display: grid; grid-template-columns: 1fr 1fr auto; align-items: end; gap: 7px; }.create-form button { margin: 0; height: 34px; }.description-input { margin-top: 0; }.add-track { align-items: flex-start; flex-direction: column; }.add-track-controls { width: 100%; }}
.flip-list-move, .flip-list-enter-active, .flip-list-leave-active { transition: transform .3s var(--spring-soft), opacity .22s var(--spring-soft); }
