.flip-list-leave-active { position: absolute; }

@media (max-width: 560px) { .playlists-hero { align-items: flex-start; }.hero-mark { display: none; }.playlist-sidebar { display: block; }.playlist-tab { margin-bottom: 4px; }.create-form { display: block; }.create-form button { margin-top: 8px; }.add-track-controls { flex-direction: column; align-items: stretch; }.add-track-controls select { width: 100%; }.add-track-controls button { width: 100%; }.track-row { grid-template-columns: 22px 43px minmax(0, 1fr) 27px; gap: 8px; }.track-album { display: none; }.playlist-rule { flex-direction: column; gap: 7px; }}
</style>
